                    del resting_orders[buy_id]
            else:
                break

        # Rest remaining qty if limit order
        if qty > 0 and is_limit:
            resting_orders[sell_id] = {'side': 'sell', 'price': price, 'qty': qty, 'arrival': arrival_counter}
            heapq.heappush(resting_sells, (price, arrival_counter, sell_id))

        arrival_counter += 1

    for order in orders:
        if order[0] == 'limit':
            _, order_id, side, price, qty = order
            if side == 'buy':
                match_incoming_buy(order_id, price, qty, True)
            else:
                match_incoming_sell(order_id, price, qty, True)

        elif order[0] == 'ioc':
            _, order_id, side, price, qty = order
            if side == 'buy':
                match_incoming_buy(order_id, price, qty, False)
            else:
                match_incoming_sell(order_id, price, qty, False)

        elif order[0] == 'market':
            _, order_id, side, qty = order
            if side == 'buy':
                match_incoming_buy(order_id, float('inf'), qty, False)
            else:
                match_incoming_sell(order_id, 0, qty, False)

        elif order[0] == 'cancel':
            _, order_id = order
            if order_id in resting_orders:
                del resting_orders[order_id]

    return trades
